"""Local, non-binding service basket. No backend or payment-success claims."""
from pricing import PLANS,T
from catalogue import catalogue
from html import escape as E
import json
COPY={
'en':{'title':'Your next chapter.<br>In one basket.','intro':'Build a project shortlist. These are starting prices, not a confirmed order. Kenny confirms your scope and final quote before payment.','label':'Shopping basket','add':'Add package','remove':'Remove','qty':'Projects','empty':'Your basket is empty. Choose a package to begin.','total':'Estimated starting total','continue':'Review payment stages','browse':'Explore all packages','note':'Preview flow: no order is saved on a server. Package IDs and quantities are saved only in this browser. Payment receipts require a future backend and verification.','estimate':'Starting price · final quote required','saved':'Basket updated','storage':'Browser storage is unavailable. Your basket works on this page; keep this tab open.','choose':'Choose a package or service'},
'zh':{'title':'你的下一章，<br>从购物篮开始。','intro':'先把心仪套餐加入清单。这里显示起价，尚未成立订单；付款前由 Kenny 确认范围与最终报价。','label':'购物篮','add':'加入套餐','remove':'移除','qty':'项目数量','empty':'购物篮暂无套餐，请先选择。','total':'预计起价合计','continue':'核对付款阶段','browse':'查看所有套餐','note':'流程预览：订单尚未存入服务器。仅套餐编号和数量保存在此浏览器；凭证上传与到账核实将在接入后台后启用。','estimate':'套餐起价 · 需确认最终报价','saved':'购物篮已更新','storage':'浏览器无法保存购物篮；此页仍可操作，请保持此标签页打开。','choose':'选择套餐或服务'},
'ms':{'title':'Bab seterusnya.<br>Dalam satu troli.','intro':'Senaraikan pakej pilihan. Ini harga permulaan, bukan pesanan disahkan. Kenny mengesahkan skop dan sebut harga sebelum bayaran.','label':'Troli','add':'Tambah pakej','remove':'Buang','qty':'Bilangan projek','empty':'Troli anda kosong. Pilih pakej untuk bermula.','total':'Anggaran jumlah permulaan','continue':'Semak peringkat bayaran','browse':'Lihat semua pakej','note':'Pratonton: tiada pesanan disimpan pada pelayan. Hanya ID pakej dan kuantiti disimpan dalam pelayar ini. Muat naik bukti dan pengesahan dana memerlukan backend kelak.','estimate':'Harga permulaan · sebut harga akhir diperlukan','saved':'Troli dikemas kini','storage':'Storan pelayar tidak tersedia. Troli berfungsi pada halaman ini; kekalkan tab terbuka.','choose':'Pilih pakej atau perkhidmatan'}}
def render(prefix,lang):
 c=COPY[lang];plans=catalogue(lang)
 out='<section class="order-hero"><span class="service-eyebrow">KENNY STUDIO / '+c['label'].upper()+'</span><h1>'+c['title']+'</h1><p class="service-lead">'+c['intro']+'</p></section><ol class="checkout-steps"><li aria-current="step">01 / '+c['label']+'</li><li>02 / '+T(('Review','核对','Semak'),lang)+'</li><li>03 / '+T(('Payment & PDF','付款与 PDF','Bayaran & PDF'),lang)+'</li></ol><div class="payment-layout"><section class="order-form-panel"><div class="cart-add"><label>'+c['choose']+'<select id="cart-package">'+''.join('<option value="'+p['id']+'">'+E(p['name'])+' — RM'+format(p['price'],',')+'</option>' for p in plans)+'</select></label><button type="button" data-cart-add class="service-button">'+c['add']+' +</button></div><div data-cart-items></div><label>'+T(('Your business, goals, pages, features and design requirements','你的业务、目标、页面、功能及设计要求','Perniagaan, matlamat, halaman, fungsi dan keperluan reka bentuk'),lang)+'<textarea id="cart-requirements" rows="5" maxlength="3000"></textarea></label><button data-cart-request type="button" class="service-button">'+T(('Send shortlist & requirements via WhatsApp','通过 WhatsApp 发送清单与需求','Hantar senarai & keperluan melalui WhatsApp'),lang)+' ↗</button><p>'+T(('Only you can send this message. Requirements stay in this tab’s session storage for checkout, not on a server. Monthly services cover selected periods only, without automatic renewal.','仅在你选择发送时打开消息。需求暂存在此标签页的会话存储以带入结账，不会存入服务器；月度服务仅包含所选月份，不自动续订。','Hanya anda menghantar mesej ini. Keperluan kekal dalam storan sesi tab untuk pembayaran, bukan pada pelayan. Perkhidmatan bulanan hanya untuk tempoh dipilih tanpa pembaharuan automatik.'),lang)+'</p><p role="status" data-cart-status></p><a href="'+prefix+'pricing/" class="service-text-link">'+c['browse']+' ↗</a></section><aside class="order-estimate payment-total"><span class="service-eyebrow">'+c['total']+'</span><strong data-cart-total class="cart-total">RM0.00</strong><p>'+c['estimate']+'</p><a data-cart-checkout class="service-button" href="'+prefix+'payment/" aria-disabled="true">'+c['continue']+' ↗</a><p class="service-note">'+c['note']+'</p></aside></div>'
 return out+'<script id="cart-options" type="application/json">'+json.dumps({'copy':c,'plans':plans},ensure_ascii=False).replace('</','<\\/')+'</script>'
